/**
 * Validate a date string in YYYY-MM-DD format.
 * @param {string} text
 * @returns {boolean}
 */
export function isValidDate(text) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(text)) {
    return false;
  }
  const date = new Date(text + 'T00:00:00Z');
  if (isNaN(date.getTime())) {
    return false;
  }
  // Verify round-trip: the parsed date should serialize back to the same string
  return date.toISOString().split('T')[0] === text;
}

/**
 * Add n days to a date string, working in UTC.
 * @param {string} date - YYYY-MM-DD format
 * @param {number} n - number of days to add (can be negative)
 * @returns {string} - YYYY-MM-DD format
 */
export function addDays(date, n) {
  const d = new Date(date + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().split('T')[0];
}

/**
 * Calculate days between two dates (b minus a), in whole days, in UTC.
 * @param {string} a - YYYY-MM-DD format
 * @param {string} b - YYYY-MM-DD format
 * @returns {number} - b - a in whole days
 */
export function daysBetween(a, b) {
  const dateA = new Date(a + 'T00:00:00Z');
  const dateB = new Date(b + 'T00:00:00Z');
  const diffMs = dateB.getTime() - dateA.getTime();
  return Math.floor(diffMs / (1000 * 60 * 60 * 24));
}

/**
 * Get the last day of the month for a given date, in UTC.
 * @param {string} date - YYYY-MM-DD format
 * @returns {string} - YYYY-MM-DD format
 */
export function lastDayOfMonth(date) {
  const d = new Date(date + 'T00:00:00Z');
  const year = d.getUTCFullYear();
  const month = d.getUTCMonth();
  const nextMonth = new Date(Date.UTC(year, month + 1, 1));
  nextMonth.setUTCDate(0);
  return nextMonth.toISOString().split('T')[0];
}

/**
 * Calculate the due date based on payment terms.
 * @param {string} issueDate - YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string} - YYYY-MM-DD format
 */
export function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return lastDayOfMonth(issueDate);
    default:
      return null;
  }
}

/** Every error code the project returns, with a one-line message. Codes are UPPER_SNAKE_CASE. */
export const ERRORS = {
  AMOUNT_INVALID: 'Amount must be a whole, positive number of cents.',
  CUSTOMER_INVALID: 'A customer needs an id, a name and a valid email.',
  CUSTOMER_NOT_FOUND: 'No customer with that id.',
  DATE_INVALID: 'Issue date must be a valid date in YYYY-MM-DD format.',
  DISCOUNT_INVALID: 'Discount percent must be a number from 0 to 100.',
  LINE_NOT_FOUND: 'That SKU is not on the invoice.',
  NO_LINES: 'An invoice must have at least one line.',
  NOT_DRAFT: 'Can only modify invoices with status "draft".',
  NOT_ISSUED: 'Can only record payments on invoices with status "issued" or "partially_paid".',
  OVERPAYMENT: 'Payment amount exceeds the balance due.',
  QTY_INVALID: 'Quantity must be a positive integer.',
  TERMS_INVALID: 'Payment terms must be "NET14", "NET30", or "EOM".',
  UNKNOWN_SKU: 'No product with that SKU in the catalogue.',
};

/**
 * The message for an error code.
 * @param {string} code
 * @returns {string}
 */
export function message(code) {
  return ERRORS[code] ?? 'Unknown error.';
}
